	return nil
}

func (p *parser) blockContents() error {
	errOpenCurlyBrace := p.openCurlyBrace()
	if errOpenCurlyBrace != nil {
		// single-server configs don't need curly braces
		p.cursor--
	}

	err := p.directives()
	if err != nil {
		return err
	}

	// only look for close curly brace if there was an opening
	if errOpenCurlyBrace == nil {
		err = p.closeCurlyBrace()
		if err != nil {
			return err
		}
	}

	return nil
}

// directives parses through all the lines for directives
// and it expects the next token to be the first
// directive. It goes until EOF or closing curly brace
// which ends the server block.
func (p *parser) directives() error {
	for p.Next() {
		// end of server block
		if p.Val() == "}" {
			// p.nesting has already been decremented
			break
		}

		// special case: import directive replaces tokens during parse-time
		if p.Val() == "import" {
			err := p.doImport(1)
			if err != nil {
				return err
			}
			p.cursor-- // cursor is advanced when we continue, so roll back one more
			continue
		}

		// normal case: parse a directive as a new segment
		// (a "segment" is a line which starts with a directive
		// and which ends at the end of the line or at the end of
		// the block that is opened at the end of the line)
		if err := p.directive(); err != nil {
			return err
		}
	}

	return nil
}

// doImport swaps out the import directive and its argument
// (a total of 2 tokens) with the tokens in the specified file
// or globbing pattern. When the function returns, the cursor
// is on the token before where the import directive was. In
// other words, call Next() to access the first token that was
// imported.
func (p *parser) doImport(nesting int) error {
	// syntax checks
	if !p.NextArg() {
		return p.ArgErr()
	}
	importPattern := p.Val()
	if importPattern == "" {
		return p.Err("Import requires a non-empty filepath")
	}

	// grab remaining args as placeholder replacements
	args := p.RemainingArgs()
	argCount := len(args)

	// set up a replacer for non-variadic args replacement
	repl := caddy.NewEmptyReplacer()
	repl.Map(func(key string) (any, bool) {
		if matches := argsRegexpIndexDeprecated.FindStringSubmatch(key); len(matches) > 0 {
			value, err := strconv.Atoi(matches[1])
			if err != nil {
				caddy.Log().Named("caddyfile").Warn(
					"Placeholder {args." + matches[1] + "} has an invalid index")
				return nil, false
			}
			if value >= argCount {
				caddy.Log().Named("caddyfile").Warn(
					"Placeholder {args." + matches[1] + "} index is out of bounds, only " + strconv.Itoa(argCount) + " argument(s) exist")
				return nil, false
			}
			caddy.Log().Named("caddyfile").Warn(
				"Placeholder {args." + matches[1] + "} deprecated, use {args[" + matches[1] + "]} instead")
			return args[value], true
		}

		if matches := argsRegexpIndex.FindStringSubmatch(key); len(matches) > 0 {
			if strings.Contains(matches[1], ":") {
				caddy.Log().Named("caddyfile").Warn(
					"Variadic placeholder {args[" + matches[1] + "]} must be a token on its own")
				return nil, false
			}
			value, err := strconv.Atoi(matches[1])
			if err != nil {
				caddy.Log().Named("caddyfile").Warn(
					"Placeholder {args[" + matches[1] + "]} has an invalid index")
				return nil, false
			}
			if value >= argCount {
				caddy.Log().Named("caddyfile").Warn(
					"Placeholder {args[" + matches[1] + "]} index is out of bounds, only " + strconv.Itoa(argCount) + " argument(s) exist")
				return nil, false
			}
			return args[value], true
		}

		return nil, false
	})

	// splice out the import directive and its arguments
	// (2 tokens, plus the length of args)
	tokensBefore := p.tokens[:p.cursor-1-argCount]
	tokensAfter := p.tokens[p.cursor+1:]
	var importedTokens []Token
	var nodes []string

	// first check snippets. That is a simple, non-recursive replacement
	if p.definedSnippets != nil && p.definedSnippets[importPattern] != nil {
		importedTokens = p.definedSnippets[importPattern]
		if len(importedTokens) > 0 {
			firstToken := importedTokens[0]
			snippetNode := fmt.Sprintf("%s:%s", firstToken.File, firstToken.snippetName)
			nodes = append(nodes, snippetNode)
		}
	} else {
		// make path relative to the file of the _token_ being processed rather
		// than current working directory (issue #867) and then use glob to get
		// list of matching filenames
		tokenFile := p.Dispenser.File()
		absFile, err := filepath.Abs(tokenFile)
		if err != nil {
			return p.Errf("Failed to get absolute path of file: %s: %v", tokenFile, err)
		}

		var matches []string
		var globPattern string
		if !filepath.IsAbs(importPattern) {
			baseDir := filepath.Dir(absFile)
			globPattern = filepath.Join(baseDir, importPattern)
		} else {
			globPattern = importPattern
		}

		starCount := strings.Count(globPattern, "*")
		questionCount := strings.Count(globPattern, "?")
		hasGlobClassOpen := strings.Contains(globPattern, "[")
		hasGlobClassClose := strings.Contains(globPattern, "]")
		invalidGlob := false
		if starCount > 1 {
			invalidGlob = true
		} else {
			if questionCount > 1 {
				invalidGlob = true
			} else {
				if hasGlobClassOpen {
					if hasGlobClassClose {
						invalidGlob = true
					}
				}
			}
		}
		if invalidGlob {
			// See issue #2096 - a pattern with many glob expansions can hang for too long
			return p.Errf("Glob pattern may only contain one wildcard (*), but has others: %s", globPattern)
		}
		matches, err = filepath.Glob(globPattern)

		if err != nil {
			return p.Errf("Failed to use import pattern %s: %v", importPattern, err)
		}
		if len(matches) == 0 {
			if strings.ContainsAny(globPattern, "*?[]") {
				caddy.Log().Warn("No files matching import glob pattern", zap.String("pattern", importPattern))
			} else {
				return p.Errf("File to import not found: %s", importPattern)
			}
		} else {
			// See issue #5295 - should skip any files that start with a . when iterating over them.
			sep := string(filepath.Separator)
			segGlobPattern := strings.Split(globPattern, sep)
			lastGlobSeg := segGlobPattern[len(segGlobPattern)-1]
			if strings.HasPrefix(lastGlobSeg, "*") {
				var tmpMatches []string
				for _, matchedPath := range matches {
					seg := strings.Split(matchedPath, sep)
					baseName := seg[len(seg)-1]
					if !strings.HasPrefix(baseName, ".") {
						tmpMatches = append(tmpMatches, matchedPath)
					}
				}
				matches = tmpMatches
			}
		}

		// collect all the imported tokens
		for _, importFile := range matches {
			openedFile, openErr := os.Open(importFile)
			if openErr != nil {
				return p.Errf("Could not import %s: %v", importFile, openErr)
			}
			fileInfo, statErr := openedFile.Stat()
			if statErr != nil {
				openedFile.Close()
				return p.Errf("Could not import %s: %v", importFile, statErr)
			}
			if fileInfo.IsDir() {
				openedFile.Close()
				return p.Errf("Could not import %s: is a directory", importFile)
			}
			fileInput, readErr := io.ReadAll(openedFile)
			openedFile.Close()
			if readErr != nil {
				return p.Errf("Could not read imported file %s: %v", importFile, readErr)
			}
			trimmedInput := strings.TrimSpace(string(fileInput))
			if len(fileInput) == 0 || len(trimmedInput) == 0 {
				caddy.Log().Warn("Import file is empty", zap.String("file", importFile))
			} else {
				envInput := fileInput
				envOffset := 0
				for {
					beginRel := bytes.Index(envInput[envOffset:], spanOpen)
					if beginRel < 0 {
						break
					}
					begin := beginRel + envOffset
					endRel := bytes.Index(envInput[begin+len(spanOpen):], spanClose)
					if endRel < 0 {
						break
					}
					end := endRel + begin + len(spanOpen)
					envString := envInput[begin+len(spanOpen) : end]
					if len(envString) == 0 {
						envOffset = end + len(spanClose)
						continue
					}
					envParts := strings.SplitN(string(envString), envVarDefaultDelimiter, 2)
					envVarValue, foundEnv := os.LookupEnv(envParts[0])
					if !foundEnv && len(envParts) == 2 {
						envVarValue = envParts[1]
					}
					envVarBytes := []byte(envVarValue)
					envInput = append(envInput[:begin], append(envVarBytes, envInput[end+len(spanClose):]...)...)
					envOffset = begin + len(envVarBytes)
				}
				newTokens, tokErr := Tokenize(envInput, importFile)
				if tokErr != nil {
					return p.Errf("Could not read tokens while importing %s: %v", importFile, tokErr)
				}
				absImport, absErr := filepath.Abs(importFile)
				if absErr != nil {
					return p.Errf("Failed to get absolute path of file: %s: %v", importFile, absErr)
				}
				for ti := 0; ti < len(newTokens); ti++ {
					newTokens[ti].File = absImport
				}
				importedTokens = append(importedTokens, newTokens...)
			}
		}
		nodes = matches
	}

	nodeName := p.File()
	currentSnippet := p.Token().snippetName
	if currentSnippet != "" {
		nodeName += fmt.Sprintf(":%s", currentSnippet)
	}
	p.importGraph.addNode(nodeName)
	p.importGraph.addNodes(nodes)
	for _, importedNode := range nodes {
		if edgeErr := p.importGraph.addEdge(nodeName, importedNode); edgeErr != nil {
			p.importGraph.removeNodes(nodes)
			return edgeErr
		}
	}

	// copy the tokens so we don't overwrite p.definedSnippets
	tokensCopy := make([]Token, 0, len(importedTokens))

	var (
		maybeSnippet   bool
		maybeSnippetId bool
		index          int
	)

	importFileName := p.File()
	importLine := p.Line()

	// run the argument replacer on the tokens
	// golang for range slice return a copy of value
	// similarly, append also copy value
	for i, token := range importedTokens {
		// update the token's imports to refer to import directive filename, line number and snippet name if there is one
		var importRef string
		if token.snippetName != "" {
			importRef = fmt.Sprintf("%s:%d (import %s)", importFileName, importLine, token.snippetName)
		} else {
			importRef = fmt.Sprintf("%s:%d (import)", importFileName, importLine)
		}
		token.imports = append(token.imports, importRef)

		// naive way of determine snippets, as snippets definition can only follow name + block
		// format, won't check for nesting correctness or any other error, that's what parser does.
		if !maybeSnippet && nesting == 0 {
			// first of the line
			if i == 0 || importedTokens[i-1].File != token.File || importedTokens[i-1].Line+importedTokens[i-1].NumLineBreaks() < token.Line {
				index = 0
			} else {
				index++
			}

			if index == 0 {
				tokenText := token.Text
				if len(tokenText) >= 3 {
					if strings.HasPrefix(tokenText, "(") {
						if strings.HasSuffix(tokenText, ")") {
							maybeSnippetId = true
						}
					}
				}
			}
		}

		switch token.Text {
		case "{":
			nesting++
			if index == 1 {
				if maybeSnippetId {
					if nesting == 1 {
						maybeSnippet = true
						maybeSnippetId = false
					}
				}
			}
		case "}":
			nesting--
			if nesting == 0 {
				if maybeSnippet {
					maybeSnippet = false
				}
			}
		}

		if maybeSnippet {
			tokensCopy = append(tokensCopy, token)
		} else {
			foundVariadic := false
			startIndex := 0
			endIndex := 0
			tokenText := token.Text
			if strings.HasPrefix(tokenText, "{args[") {
				if strings.HasSuffix(tokenText, "]}") {
					argRange := strings.TrimSuffix(strings.TrimPrefix(tokenText, "{args["), "]}")
					if argRange == "" {
						caddy.Log().Named("caddyfile").Warn(
							"Placeholder "+tokenText+" cannot have an empty index",
							zap.String("file", token.File+":"+strconv.Itoa(token.Line)), zap.Strings("import_chain", token.imports))
					} else {
						rangeStart, rangeEnd, foundColon := strings.Cut(argRange, ":")
						if foundColon {
							startIndex = 0
							endIndex = argCount
							parseFailed := false
							if rangeStart != "" {
								parsedStart, startErr := strconv.Atoi(rangeStart)
								if startErr != nil {
									caddy.Log().Named("caddyfile").Warn(
										"Variadic placeholder "+tokenText+" has an invalid start index",
										zap.String("file", token.File+":"+strconv.Itoa(token.Line)), zap.Strings("import_chain", token.imports))
									parseFailed = true
								} else {
									startIndex = parsedStart
								}
							}
							if !parseFailed && rangeEnd != "" {
								parsedEnd, endErr := strconv.Atoi(rangeEnd)
								if endErr != nil {
									caddy.Log().Named("caddyfile").Warn(
										"Variadic placeholder "+tokenText+" has an invalid end index",
										zap.String("file", token.File+":"+strconv.Itoa(token.Line)), zap.Strings("import_chain", token.imports))
									parseFailed = true
								} else {
									endIndex = parsedEnd
								}
							}
							if !parseFailed {
								if startIndex < 0 || startIndex > endIndex || endIndex > argCount {
									caddy.Log().Named("caddyfile").Warn(
										"Variadic placeholder "+tokenText+" indices are out of bounds, only "+strconv.Itoa(argCount)+" argument(s) exist",
										zap.String("file", token.File+":"+strconv.Itoa(token.Line)), zap.Strings("import_chain", token.imports))
								} else {
									foundVariadic = true
								}
							}
						}
					}
				}
			}
			if foundVariadic {
				replacedArgs := args[startIndex:endIndex]
				for _, arg := range replacedArgs {
					token.Text = arg
					tokensCopy = append(tokensCopy, token)
				}
			} else {
				token.Text = repl.ReplaceKnown(tokenText, "")
				tokensCopy = append(tokensCopy, token)
			}
		}

metadata.output:
			p.block.Keys = append(p.block.Keys, tkn)
		}

		// Advance token and possibly break out of loop or return error
		hasNext := p.Next()
		if expectingAnother && !hasNext {
			return p.EOFErr()
		}
		if !hasNext {
			p.eof = true
			break // EOF
		}
		if !expectingAnother && p.isNewLine() {
			break
		}
	}

	return nil
}

func (p *parser) blockContents() error {
	errOpenCurlyBrace := p.openCurlyBrace()
	if errOpenCurlyBrace != nil {
		// single-server configs don't need curly braces
		p.cursor--
	}

	err := p.directives()
	if err != nil {
		return err
	}

	// only look for close curly brace if there was an opening
	if errOpenCurlyBrace == nil {
		err = p.closeCurlyBrace()
		if err != nil {
			return err
		}
	}

	return nil
}

// directives parses through all the lines for directives
// and it expects the next token to be the first
// directive. It goes until EOF or closing curly brace
// which ends the server block.
func (p *parser) directives() error {
	for p.Next() {
		// end of server block
		if p.Val() == "}" {
			// p.nesting has already been decremented
			break
		}

		// special case: import directive replaces tokens during parse-time
		if p.Val() == "import" {
			err := p.doImport(1)
			if err != nil {
				return err
			}
			p.cursor-- // cursor is advanced when we continue, so roll back one more
			continue
		}

		// normal case: parse a directive as a new segment
		// (a "segment" is a line which starts with a directive
		// and which ends at the end of the line or at the end of
		// the block that is opened at the end of the line)
		if err := p.directive(); err != nil {
			return err
		}
	}

	return nil
}

// doImport swaps out the import directive and its argument
// (a total of 2 tokens) with the tokens in the specified file
// or globbing pattern. When the function returns, the cursor
// is on the token before where the import directive was. In
// other words, call Next() to access the first token that was
// imported.
func (p *parser) doImport(nesting int) error {
	// syntax checks
	if !p.NextArg() {
		return p.ArgErr()
	}
	importPattern := p.Val()
	if importPattern == "" {
		return p.Err("Import requires a non-empty filepath")
	}

	// grab remaining args as placeholder replacements
	args := p.RemainingArgs()
	argCount := len(args)

	// set up a replacer for non-variadic args replacement
	repl := caddy.NewEmptyReplacer()
	repl.Map(func(key string) (any, bool) {
		if matches := argsRegexpIndexDeprecated.FindStringSubmatch(key); len(matches) > 0 {
			value, err := strconv.Atoi(matches[1])
			if err != nil {
				caddy.Log().Named("caddyfile").Warn(
					"Placeholder {args." + matches[1] + "} has an invalid index")
				return nil, false
			}
			if value >= argCount {
				caddy.Log().Named("caddyfile").Warn(
					"Placeholder {args." + matches[1] + "} index is out of bounds, only " + strconv.Itoa(argCount) + " argument(s) exist")
				return nil, false
			}
			caddy.Log().Named("caddyfile").Warn(
				"Placeholder {args." + matches[1] + "} deprecated, use {args[" + matches[1] + "]} instead")
			return args[value], true
		}

		if matches := argsRegexpIndex.FindStringSubmatch(key); len(matches) > 0 {
			if strings.Contains(matches[1], ":") {
				caddy.Log().Named("caddyfile").Warn(
					"Variadic placeholder {args[" + matches[1] + "]} must be a token on its own")
				return nil, false
			}
			value, err := strconv.Atoi(matches[1])
			if err != nil {
				caddy.Log().Named("caddyfile").Warn(
					"Placeholder {args[" + matches[1] + "]} has an invalid index")
				return nil, false
			}
			if value >= argCount {
				caddy.Log().Named("caddyfile").Warn(
					"Placeholder {args[" + matches[1] + "]} index is out of bounds, only " + strconv.Itoa(argCount) + " argument(s) exist")
				return nil, false
			}
			return args[value], true
		}

		return nil, false
	})

	// splice out the import directive and its arguments
	// (2 tokens, plus the length of args)
	tokensBefore := p.tokens[:p.cursor-1-argCount]
	tokensAfter := p.tokens[p.cursor+1:]
	var importedTokens []Token
	var nodes []string

	// first check snippets. That is a simple, non-recursive replacement
	if p.definedSnippets != nil && p.definedSnippets[importPattern] != nil {
		importedTokens = p.definedSnippets[importPattern]
		if len(importedTokens) > 0 {
			firstToken := importedTokens[0]
			snippetNode := fmt.Sprintf("%s:%s", firstToken.File, firstToken.snippetName)
			nodes = append(nodes, snippetNode)
		}
	} else {
		// make path relative to the file of the _token_ being processed rather
		// than current working directory (issue #867) and then use glob to get
		// list of matching filenames
		tokenFile := p.Dispenser.File()
		absFile, err := filepath.Abs(tokenFile)
		if err != nil {
			return p.Errf("Failed to get absolute path of file: %s: %v", tokenFile, err)
		}

		var matches []string
		var globPattern string
		if !filepath.IsAbs(importPattern) {
			baseDir := filepath.Dir(absFile)
			globPattern = filepath.Join(baseDir, importPattern)
		} else {
			globPattern = importPattern
		}

		starCount := strings.Count(globPattern, "*")
		questionCount := strings.Count(globPattern, "?")
		hasGlobClassOpen := strings.Contains(globPattern, "[")
		hasGlobClassClose := strings.Contains(globPattern, "]")
		invalidGlob := false
		if starCount > 1 {
			invalidGlob = true
		} else {
			if questionCount > 1 {
				invalidGlob = true
			} else {
				if hasGlobClassOpen {
					if hasGlobClassClose {
						invalidGlob = true
					}
				}
			}
		}
		if invalidGlob {
			// See issue #2096 - a pattern with many glob expansions can hang for too long
			return p.Errf("Glob pattern may only contain one wildcard (*), but has others: %s", globPattern)
		}
		matches, err = filepath.Glob(globPattern)

		if err != nil {
			return p.Errf("Failed to use import pattern %s: %v", importPattern, err)
		}
		if len(matches) == 0 {
			if strings.ContainsAny(globPattern, "*?[]") {
				caddy.Log().Warn("No files matching import glob pattern", zap.String("pattern", importPattern))
			} else {
				return p.Errf("File to import not found: %s", importPattern)
			}
		} else {
			// See issue #5295 - should skip any files that start with a . when iterating over them.
			sep := string(filepath.Separator)
			segGlobPattern := strings.Split(globPattern, sep)
			lastGlobSeg := segGlobPattern[len(segGlobPattern)-1]
			if strings.HasPrefix(lastGlobSeg, "*") {
				var tmpMatches []string
				for _, matchedPath := range matches {
					seg := strings.Split(matchedPath, sep)
					baseName := seg[len(seg)-1]
					if !strings.HasPrefix(baseName, ".") {
						tmpMatches = append(tmpMatches, matchedPath)
					}
				}
				matches = tmpMatches
			}
		}

		// collect all the imported tokens
		for _, importFile := range matches {
			openedFile, openErr := os.Open(importFile)
			if openErr != nil {
				return p.Errf("Could not import %s: %v", importFile, openErr)
			}
			fileInfo, statErr := openedFile.Stat()
			if statErr != nil {
				openedFile.Close()
				return p.Errf("Could not import %s: %v", importFile, statErr)
			}
			if fileInfo.IsDir() {
				openedFile.Close()
				return p.Errf("Could not import %s: is a directory", importFile)
			}
			fileInput, readErr := io.ReadAll(openedFile)
			openedFile.Close()
			if readErr != nil {
				return p.Errf("Could not read imported file %s: %v", importFile, readErr)
			}
			trimmedInput := strings.TrimSpace(string(fileInput))
			if len(fileInput) == 0 || len(trimmedInput) == 0 {
				caddy.Log().Warn("Import file is empty", zap.String("file", importFile))
			} else {
				envInput := fileInput
				envOffset := 0
				for {
					beginRel := bytes.Index(envInput[envOffset:], spanOpen)
					if beginRel < 0 {
						break
					}
					begin := beginRel + envOffset
					endRel := bytes.Index(envInput[begin+len(spanOpen):], spanClose)
					if endRel < 0 {
						break
					}
					end := endRel + begin + len(spanOpen)
					envString := envInput[begin+len(spanOpen) : end]
					if len(envString) == 0 {
						envOffset = end + len(spanClose)
						continue
					}
					envParts := strings.SplitN(string(envString), envVarDefaultDelimiter, 2)
					envVarValue, foundEnv := os.LookupEnv(envParts[0])
					if !foundEnv && len(envParts) == 2 {
						envVarValue = envParts[1]
					}
					envVarBytes := []byte(envVarValue)
					envInput = append(envInput[:begin], append(envVarBytes, envInput[end+len(spanClose):]...)...)
					envOffset = begin + len(envVarBytes)
				}
				newTokens, tokErr := Tokenize(envInput, importFile)
				if tokErr != nil {
					return p.Errf("Could not read tokens while importing %s: %v", importFile, tokErr)
				}
				absImport, absErr := filepath.Abs(importFile)
				if absErr != nil {
					return p.Errf("Failed to get absolute path of file: %s: %v", importFile, absErr)
				}
				for ti := 0; ti < len(newTokens); ti++ {
					newTokens[ti].File = absImport
				}
				importedTokens = append(importedTokens, newTokens...)
			}
		}
		nodes = matches
	}

	nodeName := p.File()
	currentSnippet := p.Token().snippetName
	if currentSnippet != "" {
		nodeName += fmt.Sprintf(":%s", currentSnippet)
	}
	p.importGraph.addNode(nodeName)
	p.importGraph.addNodes(nodes)
	for _, importedNode := range nodes {
		if edgeErr := p.importGraph.addEdge(nodeName, importedNode); edgeErr != nil {
			p.importGraph.removeNodes(nodes)
			return edgeErr
		}
	}

	// copy the tokens so we don't overwrite p.definedSnippets
	tokensCopy := make([]Token, 0, len(importedTokens))

	var (
		maybeSnippet   bool
		maybeSnippetId bool
		index          int
	)

	importFileName := p.File()
	importLine := p.Line()

	// run the argument replacer on the tokens
	// golang for range slice return a copy of value
	// similarly, append also copy value
	for i, token := range importedTokens {
		// update the token's imports to refer to import directive filename, line number and snippet name if there is one
		var importRef string
		if token.snippetName != "" {
			importRef = fmt.Sprintf("%s:%d (import %s)", importFileName, importLine, token.snippetName)
		} else {
			importRef = fmt.Sprintf("%s:%d (import)", importFileName, importLine)
		}
		token.imports = append(token.imports, importRef)

		// naive way of determine snippets, as snippets definition can only follow name + block
		// format, won't check for nesting correctness or any other error, that's what parser does.
		if !maybeSnippet && nesting == 0 {
			// first of the line
			if i == 0 || importedTokens[i-1].File != token.File || importedTokens[i-1].Line+importedTokens[i-1].NumLineBreaks() < token.Line {
				index = 0
			} else {
				index++
			}

			if index == 0 {
				tokenText := token.Text
				if len(tokenText) >= 3 {
					if strings.HasPrefix(tokenText, "(") {
						if strings.HasSuffix(tokenText, ")") {
							maybeSnippetId = true
						}
					}
				}
			}
		}

		switch token.Text {
		case "{":
			nesting++
			if index == 1 {
				if maybeSnippetId {
					if nesting == 1 {
						maybeSnippet = true
						maybeSnippetId = false
					}
				}
			}
		case "}":
			nesting--
			if nesting == 0 {
				if maybeSnippet {
					maybeSnippet = false
				}
			}
		}

		if maybeSnippet {
			tokensCopy = append(tokensCopy, token)
		} else {
			foundVariadic := false
			startIndex := 0
			endIndex := 0
			tokenText := token.Text
			if strings.HasPrefix(tokenText, "{args[") {
				if strings.HasSuffix(tokenText, "]}") {
					argRange := strings.TrimSuffix(strings.TrimPrefix(tokenText, "{args["), "]}")
					if argRange == "" {
						caddy.Log().Named("caddyfile").Warn(
							"Placeholder "+tokenText+" cannot have an empty index",
							zap.String("file", token.File+":"+strconv.Itoa(token.Line)), zap.Strings("import_chain", token.imports))
					} else {
						rangeStart, rangeEnd, foundColon := strings.Cut(argRange, ":")
						if foundColon {
							startIndex = 0
							endIndex = argCount
							parseFailed := false
							if rangeStart != "" {
								parsedStart, startErr := strconv.Atoi(rangeStart)
								if startErr != nil {
									caddy.Log().Named("caddyfile").Warn(
										"Variadic placeholder "+tokenText+" has an invalid start index",
										zap.String("file", token.File+":"+strconv.Itoa(token.Line)), zap.Strings("import_chain", token.imports))
									parseFailed = true
								} else {
									startIndex = parsedStart
								}
							}
							if !parseFailed && rangeEnd != "" {
								parsedEnd, endErr := strconv.Atoi(rangeEnd)
								if endErr != nil {
									caddy.Log().Named("caddyfile").Warn(
										"Variadic placeholder "+tokenText+" has an invalid end index",
										zap.String("file", token.File+":"+strconv.Itoa(token.Line)), zap.Strings("import_chain", token.imports))
									parseFailed = true
								} else {
									endIndex = parsedEnd
								}
							}
							if !parseFailed {
								if startIndex < 0 || startIndex > endIndex || endIndex > argCount {
									caddy.Log().Named("caddyfile").Warn(
										"Variadic placeholder "+tokenText+" indices are out of bounds, only "+strconv.Itoa(argCount)+" argument(s) exist",
										zap.String("file", token.File+":"+strconv.Itoa(token.Line)), zap.Strings("import_chain", token.imports))
								} else {
									foundVariadic = true
								}
							}
						}
					}
				}
			}
			if foundVariadic {
				replacedArgs := args[startIndex:endIndex]
				for _, arg := range replacedArgs {
					token.Text = arg
					tokensCopy = append(tokensCopy, token)
				}
			} else {
				token.Text = repl.ReplaceKnown(tokenText, "")
				tokensCopy = append(tokensCopy, token)
			}
		}

state.output:
		}
	}

	// splice the imported tokens in the place of the import statement
	// and rewind cursor so Next() will land on first imported token
	p.tokens = append(tokensBefore, append(tokensCopy, tokensAfter...)...)
	p.cursor -= argCount + 1

	return nil
}

// doSingleImport lexes the individual file at importFile and returns
// its tokens or an error, if any.
func (p *parser) doSingleImport(importFile string) ([]Token, error) {
	file, err := os.Open(importFile)
	if err != nil {
		return nil, p.Errf("Could not import %s: %v", importFile, err)
	}
	defer file.Close()

	if info, err := file.Stat(); err != nil {
		return nil, p.Errf("Could not import %s: %v", importFile, err)
	} else if info.IsDir() {
		return nil, p.Errf("Could not import %s: is a directory", importFile)
	}

	input, err := io.ReadAll(file)
	if err != nil {
		return nil, p.Errf("Could not read imported file %s: %v", importFile, err)
	}

	// only warning in case of empty files
	if len(input) == 0 || len(strings.TrimSpace(string(input))) == 0 {
		caddy.Log().Warn("Import file is empty", zap.String("file", importFile))
		return []Token{}, nil
	}

	importedTokens, err := allTokens(importFile, input)
	if err != nil {
		return nil, p.Errf("Could not read tokens while importing %s: %v", importFile, err)
	}

	// Tack the file path onto these tokens so errors show the imported file's name
	// (we use full, absolute path to avoid bugs: issue #1892)
	filename, err := filepath.Abs(importFile)
	if err != nil {
		return nil, p.Errf("Failed to get absolute path of file: %s: %v", importFile, err)
	}
	for i := 0; i < len(importedTokens); i++ {
		importedTokens[i].File = filename
	}

	return importedTokens, nil
}

// directive collects tokens until the directive's scope
// closes (either end of line or end of curly brace block).
// It expects the currently-loaded token to be a directive
// (or } that ends a server block). The collected tokens
// are loaded into the current server block for later use
// by directive setup functions.
func (p *parser) directive() error {

	// a segment is a list of tokens associated with this directive
	var segment Segment

	// the directive itself is appended as a relevant token
	segment = append(segment, p.Token())

	for p.Next() {
		if p.Val() == "{" {
			p.nesting++
			if !p.isNextOnNewLine() && p.Token().wasQuoted == 0 {
				return p.Err("Unexpected next token after '{' on same line")
			}
			if p.isNewLine() {
				return p.Err("Unexpected '{' on a new line; did you mean to place the '{' on the previous line?")
			}
		} else if p.Val() == "{}" {
			if p.isNextOnNewLine() && p.Token().wasQuoted == 0 {
				return p.Err("Unexpected '{}' at end of line")
			}
		} else if p.isNewLine() && p.nesting == 0 {
			p.cursor-- // read too far
			break
		} else if p.Val() == "}" && p.nesting > 0 {
			p.nesting--
		} else if p.Val() == "}" && p.nesting == 0 {
			return p.Err("Unexpected '}' because no matching opening brace")
		} else if p.Val() == "import" && p.isNewLine() {
			if err := p.doImport(1); err != nil {
				return err
			}
			p.cursor-- // cursor is advanced when we continue, so roll back one more
			continue
		}

		segment = append(segment, p.Token())
	}

	p.block.Segments = append(p.block.Segments, segment)

	if p.nesting > 0 {
		return p.EOFErr()
	}

	return nil
}

// openCurlyBrace expects the current token to be an
// opening curly brace. This acts like an assertion
// because it returns an error if the token is not
// a opening curly brace. It does NOT advance the token.
func (p *parser) openCurlyBrace() error {
	if p.Val() != "{" {
		return p.SyntaxErr("{")
	}
	return nil
}

// closeCurlyBrace expects the current token to be
// a closing curly brace. This acts like an assertion
// because it returns an error if the token is not
// a closing curly brace. It does NOT advance the token.
func (p *parser) closeCurlyBrace() error {
	if p.Val() != "}" {
		return p.SyntaxErr("}")
	}
	return nil
}

func (p *parser) isNamedRoute() (bool, string) {
	keys := p.block.Keys
	// A named route block is a single key with parens, prefixed with &.
	if len(keys) == 1 && strings.HasPrefix(keys[0], "&(") && strings.HasSuffix(keys[0], ")") {
		return true, strings.TrimSuffix(keys[0][2:], ")")
	}
	return false, ""
}

func (p *parser) isSnippet() (bool, string) {
	keys := p.block.Keys
	// A snippet block is a single key with parens. Nothing else qualifies.
	if len(keys) == 1 && strings.HasPrefix(keys[0], "(") && strings.HasSuffix(keys[0], ")") {
		return true, strings.TrimSuffix(keys[0][1:], ")")
	}
	return false, ""
}

// read and store everything in a block for later replay.
func (p *parser) blockTokens(retainCurlies bool) ([]Token, error) {
	// block must have curlies.
	err := p.openCurlyBrace()
	if err != nil {
		return nil, err
	}
	nesting := 1 // count our own nesting
	tokens := []Token{}
	if retainCurlies {
		tokens = append(tokens, p.Token())
	}
	for p.Next() {
		if p.Val() == "}" {
			nesting--
			if nesting == 0 {
				if retainCurlies {
					tokens = append(tokens, p.Token())
				}
				break
			}
		}
		if p.Val() == "{" {
			nesting++
		}
		tokens = append(tokens, p.tokens[p.cursor])
	}
	// make sure we're matched up
	if nesting != 0 {
		return nil, p.SyntaxErr("}")
	}
	return tokens, nil
}

// ServerBlock associates any number of keys from the
// head of the server block with tokens, which are
// grouped by segments.
type ServerBlock struct {
	HasBraces    bool
	Keys         []string
	Segments     []Segment
	IsNamedRoute bool
}

// DispenseDirective returns a dispenser that contains
// all the tokens in the server block.
func (sb ServerBlock) DispenseDirective(dir string) *Dispenser {
	var tokens []Token
	for _, seg := range sb.Segments {
		if len(seg) > 0 && seg[0].Text == dir {
			tokens = append(tokens, seg...)
		}
	}
	return NewDispenser(tokens)
}

// Segment is a list of tokens which begins with a directive
// and ends at the end of the directive (either at the end of
// the line, or at the end of a block it opens).
type Segment []Token

// Directive returns the directive name for the segment.
// The directive name is the text of the first token.
func (s Segment) Directive() string {
	if len(s) > 0 {
		return s[0].Text
	}
	return ""
}

// spanOpen and spanClose are used to bound spans that
// contain the name of an environment variable.
var (
	spanOpen, spanClose    = []byte{'{', '$'}, []byte{'}'}
	envVarDefaultDelimiter = ":"
)

